export type TokenPath = keyof typeof tokens;
export type Mode = "light" | "dark";
/** CSS custom property reference for a token, e.g. cssVar("color.bg.canvas") -> "var(--dp-color-bg-canvas)". */
export function cssVar(path: TokenPath): string { return tokens[path].cssVar; }
/** Resolved value of a token in a mode (dark falls back to light when the token does not change). */
export function value<P extends TokenPath>(path: P, mode: Mode = "light"): (typeof tokens)[P]["light"] {
  const t = tokens[path] as DesignToken;
  return (mode === "dark" && t.dark !== undefined ? t.dark : t.light) as (typeof tokens)[P]["light"];
}
